#include <cstdio>

const long long MOD = 1000000007LL;

void solve(int n) {
    long long a = 1;
    long long d = 0;

    for (int i = 2; i <= n; ++i) {
        long long previousD = d;
        d = d * 3 % MOD;
        a = (a * 2 + previousD) % MOD;
    }

    std::printf("%lld\n", d);
}

int main() {
    int n;
    while (std::scanf("%d", &n) == 1) {
        solve(n);
    }
    return 0;
}

